"""Tests standard tap features using the built-in SDK tests library."""

from __future__ import annotations

import re
from os import path
from unittest import mock

import pytest
from singer_sdk.testing import get_tap_test_class

from tap_smoke_test.tap import TapSmokeTest

FIXTURE_DIR = path.join(  # noqa: PTH118
    path.dirname(path.realpath(__file__)),  # noqa: PTH120
    "../demo-data",
)

BASIC_CONFIG = {
    "streams": [
        {
            "stream_name": "test",
            "input_filename": path.join(FIXTURE_DIR, "pageviews-data.jsonl"),  # noqa: PTH118
        }
    ]
}


TestTapSmokeTest = get_tap_test_class(TapSmokeTest, config=BASIC_CONFIG)


def test_schema_gen_exception():
    config = {
        "streams": [
            {
                "stream_name": "test",
                "input_filename": path.join(FIXTURE_DIR, "pageviews-data.jsonl"),  # noqa: PTH118
                "schema_gen_exception": True,
            }
        ]
    }

    with pytest.raises(Exception, match="Smoke test schema call failing with exception"):
        TapSmokeTest(config=config, parse_env_config=False)


def test_client_exception():
    config = {
        "streams": [
            {
                "stream_name": "test",
                "input_filename": path.join(FIXTURE_DIR, "pageviews-data.jsonl"),  # noqa: PTH118
                "client_exception": True,
            }
        ]
    }

    tap = TapSmokeTest(config=config, parse_env_config=False)
    tap.run_discovery()
    with pytest.raises(Exception, match="Smoke test client failing with exception"):
        tap.sync_all()


@mock.patch("requests.get")
class TestRemote:
    def _mock_response(self, status=200, content="CONTENT", raise_for_status=None):
        mock_resp = mock.Mock()
        mock_resp.raise_for_status = mock.Mock()
        if raise_for_status:
            mock_resp.raise_for_status.side_effect = raise_for_status
        mock_resp.status_code = status
        mock_resp.ok = status == 200
        mock_resp.reason = content
        mock_resp.content = content

        def _mock_iter_lines():
            yield from content.splitlines()

        mock_resp.iter_lines = _mock_iter_lines
        return mock_resp

    def test_remote_file(self, mock_get):
        config = {
            "streams": [
                {
                    "stream_name": "test",
                    "input_filename": "https://dev.local/test/file.jsonl",
                    "client_exception": False,
                }
            ]
        }

        mock_resp = self._mock_response(
            content='{"id":1,"description":"Red-headed woodpecker","verified":true,'
            '"views":27,"created_at":"2021-09-22T01:01:05Z"}'
        )
        mock_get.return_value = mock_resp

        tap = TapSmokeTest(config=config, parse_env_config=False)
        tap.run_discovery()
        tap.sync_all()

    def test_remote_file_non_2xx(self, mock_get):
        config = {
            "streams": [
                {
                    "stream_name": "test",
                    "input_filename": "https://dev.local/test/file.jsonl",
                    "client_exception": False,
                }
            ]
        }

        mock_resp = self._mock_response(content="Not found", status=404)
        mock_get.return_value = mock_resp

        pattern = re.escape("Fetch of remote payload failed. status: [404], reason: [Not found]")
        with pytest.raises(Exception, match=pattern):
            _ = TapSmokeTest(config=config, parse_env_config=False)

"""Custom client handling, including SmokeTestStream base class."""

from __future__ import annotations

import json
import logging
import sys
from typing import TYPE_CHECKING
from urllib.parse import urlparse

from singer_sdk.streams import Stream

from tap_smoke_test.reader import HTTPReader, InputReader, LocalReader

if sys.version_info >= (3, 12):
    from typing import override
else:
    from typing_extensions import override

if TYPE_CHECKING:
    from collections.abc import Iterable

    from singer_sdk.helpers.types import Context, Record

logger = logging.getLogger(__name__)


class SmokeTestStream(Stream):
    """Stream class for SmokeTest streams."""

    @property
    def stream_config(self) -> dict:
        """Return the config for this particular stream name instance.

        Returns:
            The stream config for this stream name.
        """
        for conf in self.config["streams"]:
            if conf["stream_name"] == self.name:
                return conf

        return {}

    @property
    def reader(self) -> InputReader[str | bytes]:
        """Obtain an InputReader on input_filename's url scheme.

        Can be a local or remote file, or a web url.

        Returns:
            InputReader: An InputReader instance for the input_filename.

        Raises:
            Exception: If the input_filename's url scheme is not supported.
        """
        path = urlparse(self.stream_config["input_filename"])

        # TODO: Use match statement when we drop Python 3.9 support
        if path.scheme in ["file", ""]:
            return LocalReader(self.stream_config["input_filename"])
        elif path.scheme in ["http", "https"]:
            return HTTPReader(self.stream_config["input_filename"])
        else:
            raise Exception(f"Unsupported scheme [{path.scheme}] for input_filename.")

    @override
    def get_records(self, context: Context | None) -> Iterable[Record]:
        """Return a generator of row-type dictionary objects.

        Args:
            context: Used to identify a specific slice of the stream if partitioning is
                required for the stream. Most implementations do not require
                partitioning and should ignore the `context` argument.

        Raises:
            Exception: If the client_exception config is set to True.

        Yields:
            Each row in the stream as a dictionary.
        """
        i = 0
        while i < self.stream_config["loop_count"]:
            i += 1
            logger.debug("%s starting loop: %d", self.name, i)
            for entry in self.reader.read():
                yield json.loads(entry)

        if self.stream_config.get("client_exception", False):
            logger.warning("raising smoke test client exception")
            raise Exception("Smoke test client failing with exception")
